from torch.utils.cpp_extension import load_inline

square_matrix_multiplication_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for square matrix multiplication C = A * B
__global__ void square_matrix_multiplication_kernel(
    const float* A, const float* B, float* C, int N) {

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor square_matrix_multiplication_cuda(
    torch::Tensor A, torch::Tensor B) {

    int N = A.size(0); // Assuming square matrices N x N
    auto C = torch::zeros_like(A);

    // Define block and grid dimensions
    // For simplicity, let's use a fixed block size and calculate grid dimensions
    // A block of 16x16 threads is common for 2D operations
    dim3 block_size(16, 16);
    dim3 grid_size(
        (N + block_size.x - 1) / block_size.x,
        (N + block_size.y - 1) / block_size.y
    );

    square_matrix_multiplication_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
