import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

square_matrix_multiplication_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

// CUDA kernel for square matrix multiplication C = A * B using shared memory
__global__ void square_matrix_multiplication_kernel(
    const float* A, const float* B, float* C, int N) {

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread identifiers
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Calculate the row and column of the C element this thread is responsible for
    int row_c = blockIdx.y * blockDim.y + ty;
    int col_c = blockIdx.x * blockDim.x + tx;

    float sum = 0.0f;

    // Loop over tiles
    // Each iteration loads a new tile from global memory to shared memory
    for (int tile_idx = 0; tile_idx < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile_idx) {

        // Load tile from matrix A into shared memory As
        int global_row_A = row_c;
        int global_col_A = tile_idx * TILE_SIZE + tx;
        if (global_row_A < N && global_col_A < N) {
            As[ty][tx] = A[global_row_A * N + global_col_A];
        } else {
            As[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }

        // Load tile from matrix B into shared memory Bs
        int global_row_B = tile_idx * TILE_SIZE + ty;
        int global_col_B = col_c;
        if (global_row_B < N && global_col_B < N) {
            Bs[ty][tx] = B[global_row_B * N + global_col_B];
        } else {
            Bs[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads(); // Synchronize threads to ensure all data is loaded into shared memory

        // Perform dot product on tiles in shared memory
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads(); // Synchronize threads before next tile iteration
    }

    // Write the result to global memory C
    if (row_c < N && col_c < N) {
        C[row_c * N + col_c] = sum;
    }
}

torch::Tensor square_matrix_multiplication_cuda(
    torch::Tensor A, torch::Tensor B) {

    int N = A.size(0); // Assuming square matrices N x N
    auto C = torch.zeros_like(A);

    // Define block and grid dimensions
    const int BLOCK_SIZE = TILE_SIZE; // Block size should match TILE_SIZE for this implementation
    dim3 block_size(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid_size(
        (N + BLOCK_SIZE - 1) / BLOCK_SIZE,
        (N + BLOCK_SIZE - 1) / BLOCK_SIZE
    );

    square_matrix_multiplication_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

